 const retailerOptions=['shop','chain'].map(kind=>`<optgroup label="${kind==='shop'?'Captured shop offers':'Mainland China · dated chain references'}">${retailers.filter(r=>r.kind===kind).map(r=>`<option value="${esc(r.key)}">${esc(r.name)} · ${r.count} ${kind==='shop'?'records':'references'}</option>`).join('')}</optgroup>`).join('');
 const appearance=`<details class="retail-appearance"><summary>Store appearance <span aria-hidden="true">⌄</span></summary><div class="retail-config"><input id="retailRetailer" type="hidden"><label>Aisle title<input id="retailTitle" maxlength="60"></label><label>Display style<select id="retailTheme"><option value="bright">Bright white</option><option value="wood">Warm wood</option><option value="dark">Dark gallery</option></select></label><label>Currency<input id="retailPlanCurrency" value="USD" readonly aria-label="Plan currency USD"></label><label class="retail-color-label">Fascia color<input type="color" id="retailColor" aria-label="Fascia color"></label></div></details>`;
 const dimensionFields=[['retailWidth','bayWidth','Bay module width'],['pgUsable','usableWidth','Usable shelf width'],['pgHeight','fixtureHeight','Fixture height'],['pgDepth','shelfDepth','Default shelf depth'],['pgBase','baseHeight','Base shelf elevation'],['pgAisle','aisleWidth','Clear aisle width']];
 const fixtureEditor=`<details class="pg-fixture" id="retailFixtureSetup"><summary><strong>Fixture & dimensions</strong><span id="pgFixtureSummary"></span><span>Edit dimensions ↓</span></summary><div class="pg-fixture-body"><div class="pg-setup-note">Target-inspired planning. Enter your store’s actual fixture and packed-SKU measurements before setting the aisle.</div><div class="pg-fields"><label>Starting fixture<select id="pgPreset"><option value="custom">Current / custom dimensions</option><option value="48">48″ module · 84″ high · 19″ shelf</option><option value="36">36″ module · 72″ high · 19″ shelf</option></select></label><label>Units<select id="pgUnits"><option value="in">Inches</option><option value="cm">Centimeters</option></select></label><label>Bays<input id="retailBays" type="number" min="1" max="12" step="1"></label><label>Shelves per bay<input id="retailShelves" type="number" min="1" max="8" step="1"></label>${dimensionFields.map(([id,key,label])=>`<label>${label} <span class="pg-unit"></span><input id="${id}" type="number" data-fixture-dimension="${key}" min="0.1" step="0.125"></label>`).join('')}<label>Fixture measurement basis<select id="pgFixtureBasis"><option value="preset">Planning preset · unverified</option><option value="measured">Measured store fixture</option><option value="store-plan">Existing store planogram</option></select></label><label>Planogram ID<input id="pgPlanId" maxlength="60" placeholder="Your plan ID"></label><label>Store / aisle location<input id="pgLocation" maxlength="100" placeholder="Store number · aisle / section"></label></div><details class="pg-advanced"><summary>Spacing, header and fixture allowances</summary><div class="pg-fields">${[['pgThickness','shelfThickness','Shelf thickness'],['pgHeader','headerHeight','Header height'],['pgGap','productGap','Gap between product lines'],['pgLift','liftClearance','Product lift clearance'],['pgSetback','frontSetback','Front setback'],['pgEnds','endAllowance','Total end allowance'],['pgRear','rearAllowance','Rear frame allowance'],['pgFront','frontAllowance','Front fixture allowance'],['pgPitch','slotPitch','Shelf adjustment step']].map(([id,key,label])=>`<label>${label} <span class="pg-unit"></span><input id="${id}" data-fixture-dimension="${key}" type="number" min="0" step="0.125"></label>`).join('')}</div></details><p class="pg-preset-source">Starting sizes are generic U.S. gondola assumptions, including a 2″ reduction from module to usable width. <a href="https://www.lozier.com/wp-content/uploads/Catalog/Lozier-Catalog.pdf" target="_blank" rel="noopener">Manufacturer dimension reference ↗</a> · These are not verified Target fixture specifications.</p></div></details>`;
 const picture=p=>{const image=window.ATLAS_RETAIL_PACKS?.[p?.id]?.image||p?.image;return image?`<img src="${esc(image)}" alt="${esc(p.name)}" loading="lazy">`:'<span class="retail-photo-placeholder" aria-hidden="true">◇</span>'};
 panel.innerHTML=`
 <div class="retail-page-heading"><div><h1>Aisle planner</h1><p>Choose brands. Build a shelf that fits.</p></div><div class="retail-heading-actions"><button class="button outline" id="retailHelpOpen" data-retail-help>Help</button><button class="button" id="retailExportOpen">Save & download</button></div></div>
 <form class="retail-retailer-bar" id="retailSourceForm"><label>Shop products from<select id="retailSourceRetailer" aria-label="Shop products from retailer"><option value="">All retailers</option>${retailerOptions}</select></label><span id="retailSourceCount"></span><input type="search" id="retailSearch" aria-label="Search aisle products" placeholder="Find a product in this retailer"><button class="button outline" type="submit">Browse products ↓</button></form><p id="retailSourceNote" class="retail-source-note"></p>
 ${fixtureEditor}<div class="retail-workbench"><div class="retail-left"><section class="retail-stage" aria-label="Virtual toy aisle"><div class="retail-stage-bar"><div class="retail-tabs" role="group" aria-label="Aisle view"><button data-retail-view="plan" aria-pressed="true">Planogram</button><button data-retail-view="3d" aria-pressed="false">3D aisle</button></div>${appearance}<div class="retail-history"><button id="retailUndo" aria-label="Undo last change">↶</button><button id="retailRedo" aria-label="Redo last change">↷</button></div></div><div id="retailCanvas" class="retail-canvas" hidden><p id="retailSceneStatus" role="status">Loading your 3D aisle…</p></div><div id="retailPlan"></div><div class="retail-camera-tools" hidden role="group" aria-label="3D camera"><button data-retail-camera="orbit" aria-pressed="true">Orbit</button><button data-retail-camera="front" aria-pressed="false">Front</button><button data-retail-camera="top" aria-pressed="false">Top</button><button data-retail-camera="focus">Focus selection</button><button data-retail-camera="reset">Fit aisle</button><button id="retailQuality" aria-pressed="false">Studio render</button><button id="retailPhoto">Save image</button></div><p id="retailQualityStatus" class="retail-quality-status" hidden role="status"></p><p class="retail-stage-note">Planogram: dimensions and red fit warnings follow your entries. 3D: orbit, zoom and select products. Source artwork is illustrative; USD prices.</p></section>
 <section class="retail-picker" aria-labelledby="retailStockHeading"><div class="retail-picker-heading"><h2 id="retailStockHeading">Product library</h2><span id="retailPickerCount"></span></div><div class="retail-picker-controls"><select id="retailCategory" aria-label="Aisle product category"><option value="">All categories</option>${D.categories.map(c=>`<option>${esc(c)}</option>`).join('')}</select><select id="retailScope" aria-label="Aisle product collection"><option value="edit">Recommended edit · 12 ideas</option><option value="all">All captured products · ${all.length.toLocaleString()} records</option><option value="target">Target.com benchmarks</option><option value="saved">My saved collection</option><option value="aisle">Already in my aisle</option><option value="custom">My own products</option></select><select id="retailSort" aria-label="Aisle product order"><option value="fit">Planning fit: high first</option><option value="price">Price in USD: low first</option><option value="name">Name: A–Z</option></select></div><div class="retail-picker-actions"><span id="retailDestination"></span><button class="text-button" id="retailFillRetailer">Add a retailer edit</button><button class="text-button" id="retailUseCompare">Add comparison picks</button><button class="text-button" id="retailOwnProduct">+ My own product</button></div><div id="retailProducts" class="retail-products"></div><div class="retail-picker-pages"><button id="retailPrev">Previous</button><span id="retailPageCount"></span><button id="retailNext">Next</button></div></section>
 </div><aside class="retail-right"><section id="retailInspector" class="retail-inspector" aria-label="Selected aisle product"></section><section class="retail-health"><h2>Aisle summary</h2><div id="retailHealth"></div></section><div class="retail-templates"><button class="button outline" id="retailStarter">Load starter aisle</button><button class="text-button" id="retailClear">Start an empty aisle</button><p id="retailSavedStatus" role="status">Saved on this browser</p></div></aside></div>
 <section class="retail-buying-brief"><div class="retail-brief-heading"><div><h2>What should Target test?</h2><p>A discovery aisle for collectors and gift shoppers. An editorial starting point, with evidence you can inspect.</p></div><div class="retail-brief-controls"><label>Planning ticket ceiling · USD<input type="number" id="retailMaxTicket" min="1" max="500" step="1"></label><label>Audience<select id="retailAudience"><option value="collector">Teen & adult collectors</option><option value="family">Family gifting · age 8</option></select></label></div></div><div class="retail-strategies"><article><span>01 / Entry</span><h3>Make the first pick easy.</h3><p>Test tactile, easy-to-explain toys around $5–10. RMS’s $4.99 dumpling is a Target.com price reference.</p><a href="${D.benchmarks[0].listings[0].url}" target="_blank" rel="noopener">See the Target reference ↗</a></article><article><span>02 / Core</span><h3>Give charms a clear home.</h3><p>Group portable plush by character, with visible age labels. Mofusand’s $19.99 clip is a Target.com reference.</p><a href="${D.benchmarks[1].listings[0].url}" target="_blank" rel="noopener">See the Target reference ↗</a></article><article><span>03 / Discovery</span><h3>Keep the collector test focused.</h3><p>Trial a few distinct figure stories. Keep premium picks limited, and separate older-age collectibles from family gifting.</p><button class="text-button" data-retail-category="Blind-box figures">Find figure candidates →</button></article></div><details class="retail-methods"><summary>How the planning fit score and recommendations work</summary><p>Fit /100 is an Atlas planning heuristic: format 25 points (squishies/plush), 22 (figures), 18 (dolls); a verified single-pack USD asking price within your ceiling 25, within 1.5× 12; documented age 10, material 5, product size 5, official-brand offer or Target.com reference 10; available when checked 20, unknown 10. Family gifting subtracts 25 when age is missing or the stated minimum is over 8. No sales, margin or demand forecast is inferred.</p><p>The two Target.com records were read ${D.checked}; they are benchmarks outside the China directory. Prices and availability can change. Other products are proposed candidates; a listing elsewhere does not establish Target stocking, supply authorization, US distribution, compliance, wholesale cost or margin. Product photos can depict a series assortment. Fixture and pack measurement bases are recorded. Estimates remain labeled; fit checks use your entered geometry and do not verify the measurement or store execution approval.</p><p>Before buying: confirm the exact SKU and pack quantity, age label, sample quality, US supply rights and product documentation with the vendor. Age text is source information, not a safety approval. The family audience setting is a planning penalty, not certification.</p><a href="https://corporate.target.com/news-features/article/2026/10/target-holiday-kids-catalog" target="_blank" rel="noopener">Target’s discovery and wish-list approach · Oct 2026 ↗</a> · <a href="https://docs.blender.org/manual/en/5.0/addons/import_export/scene_gltf2.html" target="_blank" rel="noopener">Blender glTF import guide ↗</a></details></section>
 <dialog id="retailHelpDialog" aria-labelledby="retailHelpTitle"><button class="dialog-close" data-retail-close="retailHelpDialog" aria-label="Close workshop tutorial">×</button><span class="retail-guide-eyebrow">WORKSHOP TUTORIAL · UPDATED 4 NOV 2026</span><h2 id="retailHelpTitle">Build an aisle in four steps.</h2><p>Everything below works in this website. Blender is optional and only needed for further 3D editing on a computer.</p><ol class="retail-guide-steps"><li><div><h3>1 · Set the fixture.</h3><p>Open <strong>Fixture & dimensions</strong>. Set inches or centimeters, the usable shelf width, height, depth and aisle clearance. Presets are starting assumptions. Next choose <strong>Brands & products</strong>. Filter by <strong>Brand / character</strong> and <strong>Retailer</strong>, then search the captured blind boxes and squishies. Changing retailer keeps the products already in your aisle.</p><button class="text-button" data-retail-guide-go="fixture">Show fixture setup →</button></div></li><li><div><h3>2 · Choose brands & products.</h3><p>Choose a brand and retailer, then use <strong>Add to</strong> to choose the bay and shelf. In Arrange, use Planogram to set each shelf’s height and depth. In the product library, tap <strong>+ Add to aisle</strong>. On a phone, use these buttons instead of dragging.</p><button class="text-button" data-retail-guide-go="products">Show brands & products →</button></div></li><li><div><h3>3 · Arrange the shelves.</h3><p>Tap a product to edit its packed width, height, depth and SKU / DPCI. Mark measured or supplier dimensions when confirmed. Red warnings identify overlaps or packs that exceed shelf space. <strong>Facings</strong> is the number across; <strong>Units per facing</strong> is the stock count behind or above each front item. Use <strong>Move to shelf</strong> to move it, and <strong>Undo</strong> to reverse a change. Prices are USD; ≈ marks a converted estimate.</p><button class="text-button" data-retail-guide-go="selection">Show product controls →</button></div></li><li><div><h3>4 · Review and save.</h3><p>Tap <strong>Save & download</strong>. Choose an editable backup, a picture or a spreadsheet. The optional Blender section explains the separate 3D file.</p><button class="text-button" data-retail-guide-go="downloads">Show save choices →</button></div></li></ol><details class="retail-guide-faq"><summary>Where are my files and saved aisle?</summary><p>Your aisle saves automatically in this browser, on this device. It is not synced to an account. Download an <strong>editable aisle file (.json)</strong> to keep a backup or move to another device.</p><p>On iPhone, check <strong>Files → Downloads</strong> or your browser’s downloads. On a computer, check your <strong>Downloads</strong> folder. An in-app browser may offer a share or save-file prompt.</p><p>A <strong>.json</strong> file reopens on this website. A <strong>.png</strong> is a picture. A <strong>.csv</strong> opens in a spreadsheet. A <strong>.glb</strong> imports into Blender on a computer.</p></details><button class="button" data-retail-guide-go="retailer">Choose brands & products</button></dialog>
 <dialog id="retailExportDialog" aria-labelledby="retailExportTitle"><button class="dialog-close" data-retail-close="retailExportDialog" aria-label="Close retail exports">×</button><h2 id="retailExportTitle">Save or download your aisle.</h2><p>Your aisle saves automatically in this browser. Choose what you want to take with you.</p><div class="retail-download-grid"><section class="retail-download-card"><span class="retail-guide-eyebrow">KEEP EDITING · RECOMMENDED</span><h3>Save an editable backup</h3><p>Keep every product, shelf and setting. Open this file here later, or on another device.</p><button class="button" id="retailJSON">Save aisle file</button><small>Editable plan · .json · opens on this website</small><label class="button outline retail-import-label">Open saved aisle file<input id="retailImport" type="file" accept=".json,application/json" aria-label="Open saved aisle file"></label></section><section class="retail-download-card"><span class="retail-guide-eyebrow">SHARE A VIEW</span><h3>Save a picture</h3><p>Download the current 3D camera view to share. A picture cannot be edited as an aisle.</p><button class="button outline" id="retailExportPhoto">Save aisle picture</button><small>Image · .png</small></section><section class="retail-download-card"><span class="retail-guide-eyebrow">PLAN THE ASSORTMENT</span><h3>Save a spreadsheet</h3><p>Placement coordinates, fixture and pack dimensions, quantities, fit checks, USD prices and source links for Excel or Google Sheets.</p><button class="button outline" id="retailCSV">Save assortment sheet</button><small>Spreadsheet · .csv · photo links, not embedded photos</small></section></div><section class="retail-download-card pg-export-card"><span class="retail-guide-eyebrow">DIMENSIONED PLANNING DRAWING</span><h3>Save your planogram</h3><p>Front elevation, top view with aisle clearance, and the numbered placement schedule. Photos are embedded for offline use.</p><button class="button outline" id="retailPlanSVG">Save planogram drawing</button><small>Vector drawing · .svg · print to PDF from your browser. Dimension labels govern; drawing prints to fit the page.</small></section><p class="retail-download-location"><strong>On a phone?</strong> Check Files → Downloads or your browser’s downloads after saving. To move to another device, send yourself the editable aisle file and choose <strong>Open saved aisle file</strong> here.</p><details id="retailBlenderGuide" class="retail-blender-guide"><summary>Open in Blender <span>Optional · computer required</span></summary><p>Blender is a separate 3D editing app for a computer. You can build, save and share your aisle here without it.</p><ol><li><strong>Download your 3D aisle.</strong><p>Save the .glb file below. If you are on a phone, transfer it to your computer first.</p><button class="button outline" id="retailGLB">Download 3D aisle for Blender</button><small>3D scene · .glb · shelves, product display packs and labels</small></li><li><strong>Import it in Blender.</strong><p>On your computer, open Blender. Choose <strong>File → Import → glTF 2.0 (.glb/.gltf)</strong>, select the downloaded .glb, then choose <strong>Import glTF 2.0</strong>. Use <strong>Import</strong>, not File → Open.</p></li><li><strong>See the artwork and save.</strong><p>Use <strong>Material Preview</strong> in the 3D viewport to see the packaging. If the aisle is out of view, select the imported objects and use <strong>View → Frame Selected</strong>. Choose <strong>File → Save As</strong> to keep an editable .blend file.</p></li></ol><p>The export includes the aisle and product display models. The website’s room and studio lighting do not transfer. Dimensions follow your entered fixture and pack measurements; source artwork and loose squishy shapes are illustrative. Blender changes cannot be imported back into this website; keep the .json backup for that.</p><a href="https://docs.blender.org/manual/en/5.0/addons/import_export/scene_gltf2.html" target="_blank" rel="noopener">Official Blender import instructions ↗</a><details class="retail-helper-guide"><summary>Advanced: optional import script</summary><p>The manual steps above need no script. If you use Blender’s command line, the helper imports the GLB, adds a camera and lights, and saves a .blend file.</p><a href="retail/blender_import.py" download>Download command-line helper (.py)</a></details></details><p id="retailExportStatus" role="status" aria-live="polite"></p><button class="text-button" data-retail-help>Read the four-step workshop tutorial →</button></dialog>
 <dialog id="retailCustomDialog" aria-labelledby="retailCustomTitle"><button class="dialog-close" data-retail-close="retailCustomDialog" aria-label="Close custom product">×</button><h2 id="retailCustomTitle">Make room for your own idea.</h2><form id="retailCustomForm"><label>Product name<input name="name" required maxlength="180"></label><label>Brand or concept<input name="brand" maxlength="80" placeholder="My retail collection"></label><label>Category<select name="category">${D.categories.map(c=>`<option>${c}</option>`).join('')}</select></label><fieldset class="workshop-custom-dimensions"><legend>Retail pack size · <span id="workshopCustomUnits">in</span> (optional)</legend><label>Width<input type="number" name="packWidth" min="0.1" step="any"></label><label>Height<input type="number" name="packHeight" min="0.1" step="any"></label><label>Depth<input type="number" name="packDepth" min="0.1" step="any"></label></fieldset><label>Dimension basis<select name="packBasis"><option value="estimate">Estimate · verify pack</option><option value="measured">Measured retail pack</option><option value="supplier">Supplier pack sheet</option></select></label><label>SKU / DPCI<input name="sku" maxlength="60"></label><label>Product photo (optional)<input name="photo" type="file" accept="image/png,image/jpeg,image/webp"></label><p>Your image stays in this browser and your downloaded plan.</p><button class="button" type="submit">Create & add to aisle</button><p id="retailCustomStatus" role="status"></p></form></dialog>
 <p id="retailMessage" class="retail-message" role="status" hidden></p>`;
 for(const dialog of panel.querySelectorAll('dialog'))document.body.append(dialog);

 // Four task-focused views share one plan, one library and one dimension model.
 let workflowStep=stored?2:1,hasDefaultPreview=false,inspectorOpen={pack:false,source:false},shelfSettingsOpen=false;
 const flowNames=['Fixture','Brands & products','Arrange','Review'];
 const nav=document.createElement('nav');nav.className='workshop-steps';nav.setAttribute('aria-label','Aisle planning steps');
 nav.innerHTML=flowNames.map((name,i)=>`<button type="button" data-workshop-step="${i+1}"><span>${i+1}</span>${name}</button>`).join('');panel.querySelector('.retail-page-heading').after(nav);
 const fixtureSummary=document.createElement('div');fixtureSummary.className='workshop-fixture-summary';fixtureSummary.innerHTML='<span id="workshopFixtureText"></span><button class="text-button" data-pg-edit-fixture>Edit fixture</button>';nav.after(fixtureSummary);
 const picker=panel.querySelector('.retail-picker'),workbench=panel.querySelector('.retail-workbench');
 workbench.prepend(picker);picker.querySelector('h2').textContent='Brands & products';
 const brandRow=document.createElement('div');brandRow.className='workshop-brand-filter';brandRow.innerHTML='<label>Brand / character<select id="retailBrand" aria-label="Aisle brand or character"><option value="">All brands</option></select></label><div id="workshopBrandShortcuts" class="workshop-brand-shortcuts" aria-label="Featured brand filters"></div>';
 picker.querySelector('.retail-picker-heading').after(brandRow);brandRow.after($('retailSourceForm'));
 $('retailSourceForm').querySelector('label').firstChild.textContent='Retailer';$('retailSourceForm').querySelector('button').textContent='Search products';
 $('retailSearch').placeholder='Search products or characters';
