 const sourceNote=document.createElement('details');sourceNote.className='workshop-source-note';sourceNote.innerHTML='<summary>About captured products</summary>';sourceNote.append($('retailSourceNote'));filters.after(sourceNote);
 picker.querySelector('.retail-picker-pages').after(sourceNote);
 const options=document.createElement('details');options.className='workshop-library-options';options.innerHTML='<summary>Add several products</summary>';options.append($('retailFillRetailer'),$('retailUseCompare'));picker.querySelector('.retail-picker-actions').append(options);
 $('retailOwnProduct').textContent='+ Add my own SKU';filters.after($('retailOwnProduct'));picker.querySelector('.retail-picker-pages').after(picker.querySelector('.retail-picker-actions'));
