 const shelfTarget=document.createElement('label');shelfTarget.className='workshop-shelf-target';shelfTarget.innerHTML='Add to<select id="workshopShelfTarget" aria-label="Add product to bay and shelf"></select>';picker.querySelector('#retailProducts').before(shelfTarget);$('workshopShelfTarget').onchange=e=>selectShelf(e.target.value);
 const review=document.createElement('section');review.id='workshopReview';review.className='workshop-review';review.innerHTML='<h2>Review your plan</h2><p>Resolve fit issues, confirm measurements, then save a plan to share.</p><div id="workshopReviewChecks"></div><details class="workshop-schedule"><summary>Placement schedule</summary><div id="workshopSchedule"></div></details>';workbench.after(review);
 review.append(panel.querySelector('.retail-health'));$('retailFixtureSetup').querySelector('.pg-fixture-body').append(panel.querySelector('.retail-templates'));
 const brief=document.createElement('details');brief.className='workshop-recommendations';brief.innerHTML='<summary>Assortment ideas & buying notes</summary>';brief.append(panel.querySelector('.retail-buying-brief'));review.append(brief);
 const footer=document.createElement('div');footer.className='workshop-flow-footer';footer.innerHTML='<button class="button outline" id="workshopPrevious">Back</button><span id="workshopStepHelp"></span><button class="button" id="workshopNext">Choose brands & products →</button>';review.after(footer);
 const brandKey=value=>String(value||'Brand not disclosed').normalize('NFKC').toLowerCase().replace(/[^\p{L}\p{N}]/gu,'');
